import{_ as o,o as a,c as r,a2 as t}from"./chunks/framework.CfwCq2QB.js";const f=JSON.parse('{"title":"安装","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),i={name:"guide/install.md"};function l(d,e,c,h,s,n){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><h2 id="chrome-推荐" tabindex="-1">Chrome（推荐） <a class="header-anchor" href="#chrome-推荐" aria-label="Permalink to &quot;Chrome（推荐）&quot;">​</a></h2><p>从 <a href="https://chrome.google.com/webstore/detail/devgo/kcofdbjhicjdbmldlcffcijglkifnnjn" target="_blank" rel="noreferrer">Chrome 应用商店</a> 安装，可自动更新。</p><p>安装后点浏览器工具栏的拼图图标，把 DevGo 固定到工具栏，日常用 <code>Alt+1</code>（macOS 为 <code>⌥1</code>）随时唤起弹窗。</p><h2 id="edge-及其他-chromium-内核浏览器" tabindex="-1">Edge 及其他 Chromium 内核浏览器 <a class="header-anchor" href="#edge-及其他-chromium-内核浏览器" aria-label="Permalink to &quot;Edge 及其他 Chromium 内核浏览器&quot;">​</a></h2><p>可以直接安装 Chrome 应用商店版本：打开 Edge 的 <code>扩展 → 管理扩展</code>，开启左下角「允许来自其他应用商店的扩展」，再进入上面的商店链接点安装。</p><h2 id="firefox" tabindex="-1">Firefox <a class="header-anchor" href="#firefox" aria-label="Permalink to &quot;Firefox&quot;">​</a></h2><p>从 <a href="https://github.com/fedtop/DevGo/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 下载最新的 <code>dev-go-*.firefox.zip</code> 并解压，然后：</p><ol><li>打开 <code>about:debugging#/runtime/this-firefox</code></li><li>点「临时载入附加组件」，选择解压目录里的 <code>manifest.json</code></li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Firefox 的「临时载入」重启浏览器后会失效，每次启动需要重新载入；持续使用的正式版本需要等上架 Mozilla 商店（AMO）。另外，Firefox 下代理切换暂不可用，详见 <a href="/dev-go-docs/faq/#firefox-里代理切换不可用">FAQ</a>。</p></div><h2 id="离线安装-chrome-无法访问商店时" tabindex="-1">离线安装（Chrome，无法访问商店时） <a class="header-anchor" href="#离线安装-chrome-无法访问商店时" aria-label="Permalink to &quot;离线安装（Chrome，无法访问商店时）&quot;">​</a></h2><ol><li>从 <a href="https://github.com/fedtop/DevGo/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 下载 <code>dev-go-*-chrome.zip</code> 并解压</li><li>打开 <code>chrome://extensions</code>，右上角开启「开发者模式」</li><li>点「加载已解压的扩展程序」，选择解压出的目录</li></ol><p>离线安装的扩展不会自动更新，升级时需要重新下载并覆盖：解压新版本后，在 <code>chrome://extensions</code> 的 DevGo 卡片上点「重新加载」即可。</p><h2 id="验证安装成功" tabindex="-1">验证安装成功 <a class="header-anchor" href="#验证安装成功" aria-label="Permalink to &quot;验证安装成功&quot;">​</a></h2><p>打开任意网页，按 <code>Alt+1</code> 能弹出 DevGo 面板、网页右侧能看到悬浮快捷栏，就说明安装成功。接着去 <a href="/dev-go-docs/guide/quick-start.html">快速上手</a>。</p>',15)])])}const u=o(i,[["render",l]]);export{f as __pageData,u as default};
